<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {api,uncertainMessage} from '../api'
import {operationStatus} from '../nativeStatus'
import MailCenter from './MailCenter.vue'
import GameImage from './GameImage.vue'
import RewardEvidence from './RewardEvidence.vue'
const props=defineProps<{record:any,links:any[],disabled?:boolean}>()
const emit=defineEmits<{action:[kind:string],note:[text:string],inspect:[id:string]}>()
const scenes=[{id:'reward',name:'奖励没到账'},{id:'stuck',name:'卡地图'},{id:'equipment',name:'装备异常'},{id:'quest',name:'任务卡住'}]
const scene=ref(['reward','mail'].includes(props.record.category)?'reward':props.record.category==='unlock'?'equipment':'stuck')
const saved=ref<any>(null),busy=ref(false),error=ref(''),originalId=ref(''),original=ref<any>(null),mailOperation=ref(''),checked=ref<string[]>([])
const steps:Record<string,string[]>={reward:['核对账号、角色与原操作的目标一致','检查原操作状态和完整附件分页','区分未领、领取标记、删除与记录缺失','向玩家核实游戏内结果，再决定是否补偿'],stuck:['核对角色归属、登录状态与最近存档时间','记录玩家所处地图与断线现象','检查维护条件，再预览返回城镇等维护动作','重新登录核实位置，并记录处理结果'],equipment:['核对装备部位、物品编号与当前存档','检查强化、附魔、耐久或解锁等待记录','修改前核对维护窗口和影响预览','重新登录核实装备，并关联原操作'],quest:['记录任务编号、当前阶段和玩家反馈','核对任务记录与前置条件','仅使用已支持任务的修复预览','游戏内核实后续任务，并记录结果']}
const checklist=computed(()=>steps[scene.value]||[])
let alive=true
async function load(){if(!props.record.charac_no)return;busy.value=true;error.value='';try{const r=await api('/characters/'+props.record.charac_no+'/overview');if(!alive)return;if(Number(r.character.uid)!==Number(props.record.uid))throw new Error('当前角色归属与问题记录不一致，请先核对。');saved.value=r}catch(e){if(alive)error.value=uncertainMessage(e)}finally{if(alive)busy.value=false}}
async function inspect(){if(busy.value)return;error.value='';original.value=null;mailOperation.value='';if(!/^[a-f0-9]{32}$/.test(originalId.value)){error.value='请输入32位原操作编号。';return}busy.value=true;try{const r=await api('/operations/'+originalId.value);if(!alive)return;if(Number(r.request?.uid)!==Number(props.record.uid)||(props.record.charac_no&&r.request?.charac_no&&Number(r.request.charac_no)!==Number(props.record.charac_no)))throw new Error('原操作目标与当前问题不一致，请核对编号。');original.value=r;if(['mail','reward'].includes(r.action))mailOperation.value=originalId.value}catch(e){if(alive)error.value=uncertainMessage(e)}finally{if(alive)busy.value=false}}
function addNote(){const selected=checklist.value.filter(text=>checked.value.includes(scene.value+':'+text));if(selected.length)emit('note','【'+scenes.find(s=>s.id===scene.value)?.name+'排查】\n'+selected.map(text=>'已核对：'+text).join('\n')+'\n客户端结果：待补充')}
function date(value:any){return value?String(value).replace('T',' '):'未知'}
onMounted(()=>void load())
onBeforeUnmount(()=>{alive=false})
</script>
<template><section class="investigation" aria-label="玩家场景排查">
 <nav class="investigation-tabs" aria-label="排查场景"><button v-for="s in scenes" :key="s.id" :aria-pressed="scene===s.id" :disabled="disabled" @click="scene=s.id">{{s.name}}</button></nav>
 <div class="investigation-grid"><section><h4>核对顺序</h4><label v-for="step in checklist" :key="scene+step" class="investigation-check"><input v-model="checked" type="checkbox" :value="scene+':'+step">{{step}}</label><button :disabled="disabled||!checklist.some(s=>checked.includes(scene+':'+s))" @click="addNote">加入处理记录草稿</button><p class="field-hint">勾选仅保存在当前页面；追加到下方处理记录并保存后才进入时间线。</p></section>
 <section><div class="section-title"><h4>当前角色存档</h4><button :disabled="busy||!record.charac_no" @click="load">刷新只读存档</button></div><p v-if="!record.charac_no" class="field-hint">这是账号级问题；先核对具体角色编号后再进行角色维护。</p><p v-if="error" class="submit-error" role="alert">{{error}}</p><template v-if="saved"><p><b>{{saved.character.charac_name}}</b> #{{saved.character.charac_no}} · UID {{saved.character.uid}}</p><p>账号登录：{{saved.account_online?.login_status===1?'在线':saved.account_online?.login_status===0?'离线':'未知'}} · Lv.{{saved.character.lev}}</p><p>最近游戏存档：{{date(saved.play_state?.last_play_time||saved.character.last_play_time)}}</p><div v-if="scene==='equipment'" class="investigation-equipment"><span v-for="item in saved.equipment.items" :key="item.slot" :title="item.slot_label"><GameImage :image="item.image" :label="item.name||'#'+item.id" :rarity="item.rarity" :rarity-name="item.rarity_name"/><small>{{item.slot_label}} · {{item.name}}</small></span></div><p class="field-hint">{{saved.snapshot_note}}</p></template><div v-if="scene!=='reward'" class="button-row"><button :disabled="disabled||!record.charac_no" @click="emit('action',scene==='stuck'?'rescue':scene==='quest'?'quests':'equipment')">{{scene==='stuck'?'核对返回城镇维护':scene==='quest'?'核对任务与修复预览':'查看装备完整存档'}}</button><button v-if="scene==='equipment'" :disabled="disabled||!record.charac_no" @click="emit('action','unlock')">排查装备解锁</button></div></section></div>
 <template v-if="scene==='reward'"><RewardEvidence :committed="original?.status==='committed'"/><form class="toolbar" @submit.prevent="inspect"><label>原操作编号<input v-model="originalId" aria-label="排查原操作编号" maxlength="32" placeholder="32位原操作编号"></label><button :disabled="busy">同屏核对原操作</button></form><div v-if="links.length" class="investigation-links"><button v-for="link in links" :key="link.operation_id" :disabled="busy" @click="originalId=link.operation_id;inspect()">已关联 {{link.operation_id}}</button></div><article v-if="original" class="investigation-original"><strong>{{operationStatus(original)}}</strong><code>{{original.operation_id}}</code><p>{{original.request.reason}}</p><button @click="emit('inspect',original.operation_id)">查看原操作完整预览与结果</button></article><MailCenter :uid="Number(record.uid)" :charac-no="Number(record.charac_no)||0" locked-target inline-details :allow-draft="false" :operation-id="mailOperation"/></template>
</section></template>
<style scoped>.investigation{border-top:1px solid var(--border-color);padding-top:16px;margin:16px 0}.investigation-tabs,.investigation-links{display:flex;flex-direction:row;flex-wrap:wrap;gap:8px}.investigation-tabs [aria-pressed=true]{background:var(--primary-10);border-color:var(--primary-color);color:var(--primary-color)}.investigation-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;margin:12px 0}.investigation-grid>section{min-width:0;padding:14px;background:var(--bg-quinary);border:1px solid var(--border-color);border-radius:var(--radius-sm)}.investigation-check{display:flex;flex-direction:row;align-items:start;gap:8px;margin:10px 0;font-size:12px}.investigation-check input{width:auto;flex:none;margin-top:4px}.investigation h4{margin:0 0 12px}.investigation p{font-size:12px;overflow-wrap:anywhere}.investigation .toolbar label{flex:1;min-width:0}.investigation-original{padding:14px;margin:12px 0;border:1px solid var(--border-color);border-radius:var(--radius-sm)}.investigation-original code{display:block;overflow-wrap:anywhere}.investigation-equipment{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.investigation-equipment>span{display:flex;gap:5px;min-width:0}.investigation-equipment small{font-size:10px;overflow-wrap:anywhere}.investigation-links button{font-size:11px;overflow-wrap:anywhere}@media(max-width:800px){.investigation-grid{grid-template-columns:1fr}.investigation-tabs{display:grid;grid-template-columns:1fr 1fr}.investigation .toolbar{flex-wrap:wrap}}</style>
